import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.impl.WeakReferenceThreadMap;
import org.apache.hadoop.fs.s3a.audit.impl.AbstractAuditSpanImpl;
import org.apache.hadoop.fs.s3a.audit.impl.AbstractOperationAuditor;
import org.apache.hadoop.fs.s3a.audit.impl.ActiveAuditManagerS3A;
import org.apache.hadoop.fs.store.audit.AuditSpan;
import org.apache.hadoop.test.AbstractHadoopTestBase;

import static org.apache.hadoop.fs.s3a.audit.AuditTestSupport.createIOStatisticsStoreForAuditing;
import static org.apache.hadoop.fs.s3a.audit.AuditTestSupport.noopAuditConfig;
import static org.apache.hadoop.fs.s3a.audit.S3AAuditConstants.AUDIT_SERVICE_CLASSNAME;
import static org.assertj.core.api.Assertions.assertThat;

/**
 * Verify that the span tracking of {@link ActiveAuditManagerS3A} does
 * not leak memory through long-lived thread references.
 * <p>
 * Before HADOOP-18091 the active span of each thread was stored in a
 * {@code ThreadLocal}; as the span referenced the audit manager, and
 * hence the auditor and the filesystem, nothing was ever released for
 * threads in long-lived thread pools.
 * <p>
 * The leak is recreated here by creating a long sequence of audit
 * managers whose auditors and spans allocate a lot of memory, and
 * using them from a long-lived thread pool. On the original code this
 * would trigger an OOM; with the weak reference map the spans are
 * released once garbage collection takes place.
 */
public class TestActiveAuditManagerThreadLeakage extends
    AbstractHadoopTestBase {

  private static final Logger LOG =
      LoggerFactory.getLogger(TestActiveAuditManagerThreadLeakage.class);

  /**
   * How many managers to sequentially create.
   */
  private static final int MANAGER_COUNT = 200;

  /**
   * Size of the long-lived thread pool.
   */
  private static final int THREAD_COUNT = 20;

  /**
   * How many spans to create in each audit manager.
   */
  private static final int SPAN_COUNT = THREAD_COUNT;

  /**
   * The long-lived thread pool; the source of the leakage.
   */
  private ExecutorService workers;

  /**
   * Count of prunings which took place in the manager teardowns.
   */
  private int pruneCount;

  @After
  public void teardown() {
    if (workers != null) {
      workers.shutdownNow();
    }
  }

  /**
   * Create and start an audit manager.
   * @param conf configuration to use.
   * @return a started audit manager.
   */
  private ActiveAuditManagerS3A createManager(Configuration conf) {
    ActiveAuditManagerS3A manager = new ActiveAuditManagerS3A(
        createIOStatisticsStoreForAuditing());
    manager.init(conf);
    manager.start();
    return manager;
  }

  /**
   * The span map starts empty; creating a span adds an entry for the
   * current thread and deactivating it removes the entry again.
   */
  @Test
  public void testSpanMapLifecycle() throws Throwable {
    try (ActiveAuditManagerS3A manager = createManager(noopAuditConfig())) {
      final WeakReferenceThreadMap<?> spanMap = manager.getActiveSpanMap();
      assertThat(spanMap.size())
          .describedAs("initial size of %s", spanMap)
          .isEqualTo(0);
      final AuditSpan span = manager.createSpan("span", null, null);
      assertThat(spanMap.size())
          .describedAs("size of %s after span creation", spanMap)
          .isEqualTo(1);
      assertThat(spanMap.getForCurrentThread())
          .describedAs("active span in %s", spanMap)
          .isSameAs(span);

      // a live span is never pruned.
      assertThat(manager.prune())
          .describedAs("prune count of %s with a live span", spanMap)
          .isEqualTo(0);

      // deactivation removes the map entry.
      span.deactivate();
      assertThat(spanMap.size())
          .describedAs("size of %s after deactivation", spanMap)
          .isEqualTo(0);

      // and the unbonded span is handed back on the next request.
      assertThat(manager.getActiveAuditSpan().isValidSpan())
          .describedAs("validity of the active span")
          .isFalse();
    }
  }

  /**
   * Create many audit managers, using each of them from a long-lived
   * thread pool. If the spans are retained by the threads then this
   * will fail with an OutOfMemoryError.
   */
  @Test
  public void testMemoryLeak() throws Throwable {
    workers = Executors.newFixedThreadPool(THREAD_COUNT);
    for (int i = 0; i < MANAGER_COUNT; i++) {
      final long consumption = createAndTestOneAuditor();
      LOG.debug("manager {} memory retained {}", i, consumption);
    }
    LOG.info("Total prune count {}; span references lost {}",
        pruneCount, MemoryHungryAuditor.getSpanReferencesLost());
  }

  /**
   * Create, use and then shut down one audit manager.
   * @return the change in free memory.
   * @throws Exception failure
   */
  private long createAndTestOneAuditor() throws Exception {
    final long original = Runtime.getRuntime().freeMemory();
    try (ActiveAuditManagerS3A auditManager =
             createManager(memoryHungryAuditConfig())) {

      // there is no guarantee that every thread of the pool is used,
      // so the thread IDs are collected from the results.
      final List<Future<Long>> futures = new ArrayList<>(SPAN_COUNT);
      final Callable<Long> operation = () -> spanningOperation(auditManager);
      for (int i = 0; i < SPAN_COUNT; i++) {
        futures.add(workers.submit(operation));
      }
      final Set<Long> threadIds = new HashSet<>();
      for (Future<Long> future : futures) {
        threadIds.add(future.get());
      }

      // one entry per thread which created a span.
      assertThat(auditManager.getActiveSpanMap().size())
          .describedAs("size of span map %s",
              auditManager.getActiveSpanMap())
          .isEqualTo(threadIds.size());

      // the worker threads have released their references, so
      // a garbage collection should make the spans collectable
      // and hence prunable.
      System.gc();
      pruneCount += auditManager.prune();
    }
    return original - Runtime.getRuntime().freeMemory();
  }

  /**
   * Create a span in the current thread and leave it active:
   * this is what used to leak.
   * @param auditManager manager to create the span in.
   * @return the ID of the current thread.
   * @throws IOException failure to create the span.
   */
  private long spanningOperation(final ActiveAuditManagerS3A auditManager)
      throws IOException {
    // pick up the unbonded span first, so that an entry is created
    // even before the real span is.
    auditManager.getActiveAuditSpan();
    final AuditSpan span = auditManager.createSpan("span", "/1", "/2");
    assertThat(span.isValidSpan())
        .describedAs("validity of %s", span)
        .isTrue();
    return Thread.currentThread().getId();
  }

  /**
   * Configuration with the memory hungry auditor.
   * @return a configuration.
   */
  private Configuration memoryHungryAuditConfig() {
    final Configuration conf = new Configuration(false);
    conf.set(AUDIT_SERVICE_CLASSNAME, MemoryHungryAuditor.NAME);
    return conf;
  }

  /**
   * An auditor which allocates a lot of memory, both in the auditor
   * itself and in every span it creates.
   * If references to spans are retained then the auditors are retained
   * too, and the test run will fail with an OOM.
   */
  public static final class MemoryHungryAuditor extends
      AbstractOperationAuditor {

    /**
     * Classname of this auditor: {@value}.
     */
    public static final String NAME =
        "org.apache.hadoop.fs.s3a.audit."
            + "TestActiveAuditManagerThreadLeakage$MemoryHungryAuditor";

    /**
     * Memory allocated per auditor.
     */
    private static final int AUDITOR_MEMORY = 8 * 1024 * 1024;

    /**
     * Memory allocated per span.
     */
    private static final int SPAN_MEMORY = 4 * 1024;

    /**
     * Count of spans created across all instances.
     */
    private static final AtomicLong SPANS_CREATED = new AtomicLong();

    /**
     * Count of span references lost across all instances.
     */
    private static final AtomicLong SPAN_REFERENCES_LOST = new AtomicLong();

    /**
     * The memory this auditor holds on to.
     */
    private final byte[] memory = new byte[AUDITOR_MEMORY];

    /**
     * The unbonded span.
     */
    private final AuditSpanS3A unbondedSpan;

    public MemoryHungryAuditor() {
      super("MemoryHungryAuditor");
      this.unbondedSpan = new MemorySpan(createSpanID(), "unbonded");
    }

    /**
     * How much memory is retained by this auditor.
     * @return the size of the memory block.
     */
    public int getMemorySize() {
      return memory.length;
    }

    @Override
    public AuditSpanS3A createSpan(
        final String operation,
        @Nullable final String path1,
        @Nullable final String path2) {
      SPANS_CREATED.incrementAndGet();
      return new MemorySpan(createSpanID(), operation);
    }

    @Override
    public AuditSpanS3A getUnbondedSpan() {
      return unbondedSpan;
    }

    @Override
    public void noteSpanReferenceLost(final long threadId) {
      SPAN_REFERENCES_LOST.incrementAndGet();
    }

    /**
     * Count of spans created by all instances of this auditor.
     * @return the count.
     */
    public static long getSpansCreated() {
      return SPANS_CREATED.get();
    }

    /**
     * Count of span references reported lost to all instances
     * of this auditor.
     * @return the count.
     */
    public static long getSpanReferencesLost() {
      return SPAN_REFERENCES_LOST.get();
    }

    /**
     * A span which also allocates memory.
     */
    private static final class MemorySpan extends AbstractAuditSpanImpl {

      /**
       * The memory this span holds on to.
       */
      private final byte[] data = new byte[SPAN_MEMORY];

      private MemorySpan(final String spanId, final String operationName) {
        super(spanId, operationName);
      }

      /**
       * How much memory is retained by this span.
       * @return the size of the memory block.
       */
      public int getDataSize() {
        return data.length;
      }

      @Override
      public void deactivate() {
        /* no-op */
      }

      @Override
      public String toString() {
        return "MemorySpan{id=" + getSpanId()
            + ", name=" + getOperationName()
            + ", size=" + getDataSize()
            + '}';
      }
    }
  }
}
